     1	﻿function Test-MtCisSpfRecordsPublished {
     2	    <#
     3	    .SYNOPSIS
     4	        Checks that every custom accepted domain publishes an SPF record that ends in -all or ~all.
     5	
     6	    .DESCRIPTION
     7	        Looks up the SPF record of each custom accepted domain and passes when a record exists and ends with a hard fail or soft fail, either directly or through a redirect. Domains in the onmicrosoft.com namespace are excluded because Microsoft manages their SPF.
     8	        CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.8, L1)
     9	
    10	    .EXAMPLE
    11	        Test-MtCisSpfRecordsPublished
    12	
    13	        Returns true if all custom domains publish an SPF record that ends in -all or ~all.
    14	
    15	    .LINK
    16	        https://maester.dev/docs/tests/CIS.M365.2.1.8
    17	    #>
    18	    [MaesterTest(
    19	        Id = 'CIS.M365.2.1.8',
    20	        Title = 'Ensure that SPF records are published for all Exchange Domains',
    21	        Product = 'defender',
    22	        Feature = 'email-authentication',
    23	        Area = 'email-protection',
    24	        ResourceType = 'Domain',
    25	        Severity = 'Medium',
    26	        UserImpact = 'Low',
    27	        ImplementationCost = 'Medium',
    28	        Mitre = ('T1566', 'T1684.002'),
    29	        Control = ('cis-m365:2.1.8', 'nist-800-53-r5:SI-8'),
    30	        Service = 'ExchangeOnline',
    31	        Author = 'JeremyFinney-lgtm'
    32	    )]
    33	    [CmdletBinding()]
    34	    [OutputType([bool])]
    35	    param()
    36	
    37	    Write-Verbose 'Getting accepted domains...'
    38	    $domains = @(Get-MtExo -Request AcceptedDomain | Where-Object { $_.InitialDomain -eq $false -and $_.IsCoExistenceDomain -eq $false })
    39	
    40	    $report = foreach ($domain in $domains) {
    41	        $name = $domain.DomainName
    42	        $detail = ''
    43	        $spf = ConvertFrom-MailAuthenticationRecordSpf -DomainName $name
    44	        if ($spf -is [string] -and ($spf -like '*not available' -or $spf -eq 'DNS lookup unavailable')) {
    45	            [pscustomobject]@{ Domain = $name; Record = $null; Pass = $null; Detail = 'DNS lookup not available' }
    46	            continue
    47	        }
    48	        $record = if ($spf.GetType().Name -eq 'SPFRecord') { $spf.record } else { $null }
    49	        $effective = $record
    50	        $redirectTargets = @()
    51	        $redirectError = $null
    52	        $redirectUnavailable = $false
    53	        $visitedDomains = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    54	        $null = $visitedDomains.Add($name)
    55	
    56	        while ($effective) {
    57	            # RFC 7208 section 5.1: a redirect is ignored when the record has an all mechanism.
    58	            $localAll = [regex]::Match([string]$effective, '(?i)(^|\s)(?<q>[+?~-]?)all(\s|$)')
    59	            if ($localAll.Success) { break }
    60	
    61	            $redirect = [regex]::Match([string]$effective, '(?i)(?:^|\s)redirect=(?<target>[^\s;]+)')
    62	            if (-not $redirect.Success) { break }
    63	            $target = $redirect.Groups['target'].Value
    64	
    65	            if ($redirectTargets.Count -ge 9) {
    66	                $redirectError = 'The redirect chain exceeds the DNS lookup limit.'
    67	                break
    68	            }
    69	            if (-not $visitedDomains.Add($target)) {
    70	                $redirectError = "The redirect chain contains a cycle at $target."
    71	                break
    72	            }
    73	
    74	            $redirectTargets += $target
    75	            $redirected = ConvertFrom-MailAuthenticationRecordSpf -DomainName $target
    76	            if ($redirected -is [string] -and ($redirected -like '*not available' -or $redirected -eq 'DNS lookup unavailable')) {
    77	                $redirectUnavailable = $true
    78	                break
    79	            }
    80	            $redirectedType = if ($null -ne $redirected) { $redirected.GetType().Name } else { $null }
    81	            $effective = if ($redirectedType -eq 'SPFRecord') { $redirected.record } else { $null }
    82	            if (-not $effective) {
    83	                $redirectError = "No SPF record was found at redirect target $target."
    84	                break
    85	            }
    86	        }
    87	
    88	        if ($redirectUnavailable) {
    89	            [pscustomobject]@{ Domain = $name; Record = $record; Pass = $null; Detail = "DNS lookup not available for $($redirectTargets[-1])" }
    90	            continue
    91	        }
    92	        $effectiveAll = [regex]::Match([string]$effective, '(?i)(^|\s)(?<q>[+?~-]?)all(\s|$)')
    93	        $pass = $effectiveAll.Success -and $effectiveAll.Groups['q'].Value -in '-', '~'
    94	        if (-not $record) {
    95	            $detail = 'No SPF record found'
    96	        } elseif ($redirectError) {
    97	            $detail = $redirectError
    98	        } elseif ($redirectTargets.Count -gt 0 -and -not $pass) {
    99	            $detail = "The effective record after redirecting to $($redirectTargets -join ' -> ') does not end with -all or ~all"
   100	        } elseif ($redirectTargets.Count -gt 0) {
   101	            $detail = "Redirects to $($redirectTargets -join ' -> ')"
   102	        }
   103	        elseif (-not $pass) {
   104	            $detail = 'The record does not end with -all or ~all'
   105	        }
   106	        [pscustomobject]@{ Domain = $name; Record = $record; Pass = $pass; Detail = $detail }
   107	    }
   108	
   109	    $unchecked = @($report | Where-Object { $null -eq $_.Pass })
   110	    $failed = @($report | Where-Object { $_.Pass -eq $false })
   111	    if ($failed.Count -gt 0) {
   112	        $testResult = $false
   113	    } elseif ($unchecked.Count -gt 0) {
   114	        Add-MtTestResultDetail -SkippedBecause NotSupported
   115	        return $null
   116	    } else {
   117	        $testResult = $true
   118	    }
   119	
   120	    $passText = if ($domains.Count -eq 0) { 'There are no custom domains, so no SPF records are required.' } else { 'All custom domains publish an SPF record that ends in -all or ~all.' }
   121	    $failText = "$($failed.Count) custom domain(s) do not publish a compliant SPF record."
   122	
   123	    $resultMd = "| Domain | SPF record | Detail | Result |`n"
   124	    $resultMd += "| --- | --- | --- | --- |`n"
   125	    foreach ($row in $report) {
   126	        $resultMd += "| $($row.Domain) | $($row.Record) | $($row.Detail) | $(if ($null -eq $row.Pass) { 'Not checked' } elseif ($row.Pass) { '✅ Pass' } else { '❌ Fail' }) |`n"
   127	    }
   128	
   129	    if ($testResult) {
   130	        $testResultMarkdown = "Well done. $passText`n`n%TestResult%"
   131	    }
   132	    else {
   133	        $testResultMarkdown = "$failText`n`n%TestResult%"
   134	    }
   135	    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $resultMd
   136	
   137	    Add-MtTestResultDetail -Result $testResultMarkdown
   138	    return $testResult
   139	}
