     1	﻿function Test-MtCisDkim {
     2	    <#
     3	    .SYNOPSIS
     4	    Checks state of DKIM for all EXO domains
     5	
     6	    .DESCRIPTION
     7	    DKIM should be enabled with a valid Exchange status for all sending domains. Initial (MOERA) and coexistence domains are excluded, as Microsoft automatically signs outbound mail for those domains.
     8	    CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.9, L1)
     9	
    10	    .EXAMPLE
    11	    Test-MtCisDkim
    12	
    13	    Returns true if every evaluated domain has a DKIM record, DKIM enabled in Exchange, and Exchange status Valid.
    14	    Initial, coexistence, and Exchange sending-disabled domains are excluded; if no domains remain, the test is skipped.
    15	
    16	    .LINK
    17	    https://maester.dev/docs/commands/Test-MtCisDkim
    18	    #>
    19	    [MaesterTest(
    20	        Id = 'CIS.M365.2.1.9',
    21	        Title = 'Ensure that DKIM is enabled for all Exchange Online Domains',
    22	        Product = 'defender',
    23	        RelatedProduct = 'exchange',
    24	        Feature = 'email-authentication',
    25	        Area = 'email-protection',
    26	        ResourceType = 'Domain',
    27	        Severity = 'Medium',
    28	        UserImpact = 'Low',
    29	        ImplementationCost = 'Medium',
    30	        Mitre = ('T1566', 'T1684.002'),
    31	        Control = ('cis-m365:2.1.9', 'nist-800-53-r5:SC-8'),
    32	        Service = 'ExchangeOnline',
    33	        Author = 'NZLostboy',
    34	        Contributor = ('JeanPhilippeGeorge', 'brianreidc7', 'amlhive-tech')
    35	    )]
    36	    [CmdletBinding()]
    37	    [OutputType([bool])]
    38	    param(
    39	        # Selector-name for the DKIM record to test..
    40	        [string]$Selector = 'selector1'
    41	    )
    42	
    43	    $dkimSigningConfigs = Get-MtExo -Request DkimSigningConfig
    44	    $acceptedDomains = Get-MtExo -Request AcceptedDomain
    45	    <# DKIM record without key for parked domains
    46	    $sendingDomains = $acceptedDomains | Where-Object {
    47	        -not $_.SendingFromDomainDisabled
    48	    }
    49	    #>
    50	
    51	    $dkimRecords = @()
    52	    foreach ($domain in $acceptedDomains) {
    53	        if ($domain.InitialDomain -eq $true -or $domain.IsCoExistenceDomain -eq $true) {
    54	            $dkimRecord = [PSCustomObject]@{
    55	                domain     = $domain.DomainName
    56	                pass       = 'Skipped'
    57	                reason     = 'Initial or coexistence domain excluded from DKIM audit (Microsoft auto-signs outbound mail for this domain)'
    58	                exchangeStatus = 'Excluded'
    59	                dkimRecord = $null
    60	            }
    61	            $dkimRecords += $dkimRecord
    62	            continue
    63	        }
    64	
    65	        $dkimSigningConfig = $dkimSigningConfigs | Where-Object {
    66	            $_.domain -eq $domain.domainname
    67	        }
    68	
    69	        if (-not $dkimSigningConfig) {
    70	            $dkimRecord = [PSCustomObject]@{
    71	                domain     = $domain.DomainName
    72	                pass       = if ($domain.SendingFromDomainDisabled) { 'Skipped' } else { 'Failed' }
    73	                reason     = if ($domain.SendingFromDomainDisabled) { 'Parked domain' } else { 'No DkimSigningConfig found for domain' }
    74	                exchangeStatus = 'Not configured'
    75	                dkimRecord = $null
    76	            }
    77	            $dkimRecords += $dkimRecord
    78	            continue
    79	        }
    80	
    81	        if ((Get-Date) -gt $dkimSigningConfig.RotateOnDate) {
    82	            if ($Selector -ne $dkimSigningConfig.SelectorAfterRotateOnDate) {
    83	                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorAfterRotateOnDate) based on EXO config"
    84	            }
    85	            $Selector = $dkimSigningConfig.SelectorAfterRotateOnDate
    86	        } else {
    87	            if ($Selector -ne $dkimSigningConfig.SelectorBeforeRotateOnDate) {
    88	                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorBeforeRotateOnDate) based on EXO config"
    89	            }
    90	            $selector = $dkimSigningConfig.SelectorBeforeRotateOnDate
    91	        }
    92	
    93	        $isMicrosoftDomain = $domain.DomainName.EndsWith(".onmicrosoft.com")
    94	        $isMicrosoftExoHybridDomain = $domain.DomainName.EndsWith(".mail.onmicrosoft.com")
    95	        $dkimDnsName = if ($isMicrosoftExoHybridDomain) {
    96	            "$($Selector)._domainkey.$($domain.DomainName)"
    97	        } elseif ($isMicrosoftDomain) {
    98	            $dkimSigningConfig."$($selector)CNAME"
    99	        } else {
   100	            "$($Selector)._domainkey.$($domain.DomainName)"
   101	        }
   102	        $dkimRecord = Get-MailAuthenticationRecord -DomainName $domain.DomainName -DkimDnsName $dkimDnsName -Records DKIM
   103	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'pass' -Value 'Failed'
   104	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'reason' -Value ''
   105	        $dkimRecord | Add-Member -MemberType NoteProperty -Name 'exchangeStatus' -Value $dkimSigningConfig.Status
   106	
   107	        if ($domain.SendingFromDomainDisabled) {
   108	            $dkimRecord.pass = 'Skipped'
   109	            $dkimRecord.reason = 'Parked domain'
   110	        } elseif (-not $dkimSigningConfig.enabled) {
   111	            $dkimRecord.pass = 'Failed'
   112	            $dkimRecord.reason = 'DKIM is disabled'
   113	        } elseif ($dkimSigningConfig.Status -ne 'Valid') {
   114	            $dkimRecord.pass = 'Failed'
   115	            $dkimRecord.reason = "Exchange DKIM status is '$($dkimSigningConfig.Status)' (expected Valid)"
   116	        } elseif ($null -ne $dkimRecord.dkimRecord -and $dkimRecord.dkimRecord.GetType().Name -eq 'DKIMRecord') {
   117	            if (-not $dkimRecord.dkimRecord.validBase64) {
   118	                $dkimRecord.reason = 'Malformed public key'
   119	            } else {
   120	                $dkimRecord.pass = 'Passed'
   121	            }
   122	        } elseif ($domain.DomainName -like '*.onmicrosoft.com') {
   123	            $dkimRecord.reason = "Recommendation: Disable sending from domain"
   124	        } elseif ($dkimRecord.dkimRecord -like '*not available') {
   125	            $dkimRecord.pass = 'Skipped'
   126	            $dkimRecord.reason = $dkimRecord.dkimRecord
   127	        } else {
   128	            $dkimRecord.reason = $dkimRecord.dkimRecord
   129	        }
   130	
   131	        $dkimRecords += $dkimRecord
   132	    }
   133	
   134	if ('Failed' -in $dkimRecords.pass) {
   135	        $testResult = $false
   136	    } elseif ('Failed' -notin $dkimRecords.pass -and 'Passed' -notin $dkimRecords.pass) {
   137	        Add-MtTestResultDetail -SkippedBecause NotSupported
   138	        return $null
   139	    } else {
   140	        $testResult = $true
   141	    }
   142	
   143	    $portalLink = 'https://security.microsoft.com/authentication?viewid=DKIM'
   144	
   145	    if ($testResult) {
   146	        $testResultMarkdown = "Well done. Your tenant's domains have DKIM configured and valid records exist.`n`n%TestResult%"
   147	    } else {
   148	        $testResultMarkdown = "Your tenant's domains do not have DKIM fully deployed. Review [EXO configuration]($portalLink) and DNS records.`n`n%TestResult%"
   149	    }
   150	
   151	    $passResult = '✅ Pass'
   152	    $failResult = '❌ Fail'
   153	    $skipResult = '🗄️ Skip'
   154	    $result = "| Domain | Result | Exchange status | Reason |`n"
   155	    $result += "| --- | --- | --- | --- |`n"
   156	    foreach ($item in $dkimRecords | Sort-Object -Property domain) {
   157	        switch ($item.pass) {
   158	            'Passed' { $itemResult = $passResult }
   159	            'Skipped' { $itemResult = $skipResult }
   160	            'Failed' { $itemResult = $failResult }
   161	        }
   162	        $result += "| $($item.domain) | $($itemResult) | $($item.exchangeStatus) | $($item.reason) |`n"
   163	    }
   164	
   165	    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $result
   166	
   167	    Add-MtTestResultDetail -Result $testResultMarkdown
   168	    return $testResult
   169	}
