     1	﻿function Test-MtCisDmarcRecordsPublished {
     2	    <#
     3	    .SYNOPSIS
     4	        Checks that every accepted domain has a DMARC policy of quarantine or reject with aggregate and forensic reporting.
     5	
     6	    .DESCRIPTION
     7	        Looks up the DMARC record that applies to each accepted domain, falling back to the organisational domain when the domain has no valid record, including a malformed record. Passes when the applied policy is quarantine or reject, covers 100 percent of mail and defines mailto addresses for aggregate (rua) and forensic (ruf) reports.
     8	        CIS Microsoft 365 Foundations Benchmark v7.0.0 (2.1.10, L1)
     9	
    10	    .EXAMPLE
    11	        Test-MtCisDmarcRecordsPublished
    12	
    13	        Returns true if all accepted domains have an enforcing DMARC policy with reporting addresses.
    14	
    15	    .LINK
    16	        https://maester.dev/docs/tests/CIS.M365.2.1.10
    17	    #>
    18	    [MaesterTest(
    19	        Id = 'CIS.M365.2.1.10',
    20	        Title = 'Ensure DMARC records for all Exchange Online domains are published',
    21	        Product = 'defender',
    22	        Feature = 'email-authentication',
    23	        Area = 'email-protection',
    24	        ResourceType = 'Domain',
    25	        Severity = 'Medium',
    26	        UserImpact = 'Low',
    27	        ImplementationCost = 'Medium',
    28	        Mitre = ('T1566', 'T1684.002'),
    29	        Control = ('cis-m365:2.1.10', 'nist-800-53-r5:SI-8'),
    30	        Service = 'ExchangeOnline',
    31	        Author = 'JeremyFinney-lgtm'
    32	    )]
    33	    [CmdletBinding()]
    34	    [OutputType([bool])]
    35	    param()
    36	
    37	    Write-Verbose 'Getting accepted domains...'
    38	    $domains = @(Get-MtExo -Request AcceptedDomain | Where-Object { $_.IsCoExistenceDomain -eq $false })
    39	
    40	    $report = foreach ($domain in $domains) {
    41	        $name = $domain.DomainName
    42	        $dmarc = $null
    43	        $source = $null
    44	        $unavailable = $false
    45	        $invalidCandidate = $null
    46	        # DMARC policy discovery uses the domain, then its organisational domain only.
    47	        $candidates = @($name, (Get-MtRegistrableDomain -DomainName $name)) | Select-Object -Unique
    48	        foreach ($candidate in $candidates) {
    49	            $found = ConvertFrom-MailAuthenticationRecordDmarc -DomainName $candidate
    50	            if ($found -is [string]) {
    51	                if ($found -like '*not available' -or $found -eq 'DNS lookup unavailable') { $unavailable = $true; break }
    52	                if ($found -eq 'Invalid DMARC record') { $invalidCandidate = $candidate }
    53	                continue
    54	            }
    55	            if ($null -ne $found -and $found.GetType().Name -eq 'DMARCRecord') {
    56	                $dmarc = $found
    57	                $source = $candidate
    58	                break
    59	            }
    60	        }
    61	        if ($unavailable) {
    62	            [pscustomobject]@{ Domain = $name; Policy = 'Not checked'; Source = 'None'; Failed = 'DNS lookup not available'; Pass = $null }
    63	            continue
    64	        }
    65	        $policy = $null
    66	        if ($dmarc) {
    67	            $policy = if ($source -ne $name -and $dmarc.policySubdomain) { $dmarc.policySubdomain } else { $dmarc.policy }
    68	        }
    69	        $checks = [ordered]@{
    70	            'Record is valid' = $null -ne $dmarc -and $dmarc.valid
    71	            'Policy is quarantine or reject' = $policy -in @('quarantine', 'reject')
    72	            'Applies to 100 percent' = $null -eq $dmarc -or $dmarc.percentage -eq 100 -or $null -eq $dmarc.percentage
    73	            'Aggregate reports (rua)' = @($dmarc.reportAggregate | Where-Object { $_.mailAddress }).Count -gt 0
    74	            'Forensic reports (ruf)' = @($dmarc.reportForensic | Where-Object { $_.mailAddress }).Count -gt 0
    75	        }
    76	        $failedChecks = @($checks.GetEnumerator() | Where-Object { -not $_.Value } | ForEach-Object { $_.Key })
    77	        [pscustomobject]@{
    78	            Domain = $name
    79	            Policy = if ($policy) { $policy } elseif ($invalidCandidate) { 'Invalid DMARC record' } else { 'No valid record' }
    80	            Source = if ($source) { $source } elseif ($invalidCandidate) { $invalidCandidate } else { 'None' }
    81	            Failed = $failedChecks -join ', '
    82	            Pass = $failedChecks.Count -eq 0
    83	        }
    84	    }
    85	    $checked = @($report | Where-Object { $null -ne $_.Pass })
    86	    $unchecked = @($report | Where-Object { $null -eq $_.Pass })
    87	    $failed = @($checked | Where-Object { -not $_.Pass })
    88	    if ($failed.Count -eq 0 -and $unchecked.Count -gt 0) {
    89	        Add-MtTestResultDetail -SkippedBecause NotSupported
    90	        return $null
    91	    }
    92	    $testResult = $failed.Count -eq 0
    93	
    94	    $passText = 'All accepted domains have an enforcing DMARC policy with reporting addresses.'
    95	    $failText = "$($failed.Count) domain(s) do not have a compliant DMARC policy."
    96	
    97	    $resultMd = "| Domain | Applied policy | Record found at | Failed checks | Result |`n"
    98	    $resultMd += "| --- | --- | --- | --- | --- |`n"
    99	    foreach ($row in $report) {
   100	        $resultMd += "| $($row.Domain) | $($row.Policy) | $($row.Source) | $(if ($row.Failed) { $row.Failed } else { 'None' }) | $(if ($null -eq $row.Pass) { 'Not checked' } elseif ($row.Pass) { '✅ Pass' } else { '❌ Fail' }) |`n"
   101	    }
   102	
   103	    if ($testResult) {
   104	        $testResultMarkdown = "Well done. $passText`n`n%TestResult%"
   105	    } else {
   106	        $testResultMarkdown = "$failText`n`n%TestResult%"
   107	    }
   108	    $testResultMarkdown = $testResultMarkdown -replace '%TestResult%', $resultMd
   109	
   110	    Add-MtTestResultDetail -Result $testResultMarkdown
   111	    return $testResult
   112	}
